package agent

import (
	"encoding/json"
)

// DevNetwork is the shared podman network: workspaces and node services meet by name.
const DevNetwork = "walroos-dev"

// WorkspaceSpec is what the hub sends to create a workspace.
type WorkspaceSpec struct {
	Name             string `json:"name"`
	RepoURL          string `json:"repo_url"`
	Branch           string `json:"branch"`            // "" = the repo's default branch
	DevcontainerPath string `json:"devcontainer_path"` // "" = standard locations, else base image
	// Devcontainer is a devcontainer.json sent inline (e.g. generated by detect). It wins over
	// the repo's own and is never written to the clone; the saved spec keeps it for rebuilds.
	Devcontainer json.RawMessage `json:"devcontainer,omitempty"`
	// Init starts a new project instead of cloning: no repo_url, the node runs git init and stages
	// these files (path → content). The user commits and adds origin from inside.
	Init map[string]string `json:"init,omitempty"`
}

// Workspace is the agent's view of a workspace, derived from podman plus in-flight work.
type Workspace struct {
	Name   string `json:"name"`
	State  string `json:"state"` // creating, running, stopped, failed, deleting
	Image  string `json:"image,omitempty"`
	User   string `json:"user,omitempty"`   // uid:gid
	Folder string `json:"folder,omitempty"` // repo path inside the container
	Error  string `json:"error,omitempty"`

	AgentDir string `json:"-"` // container dir for forwarded ssh-agent sockets, "" if not mounted
}
